async function incrementSiteStat(field){if(!useDb)return;const col=field==='app_downloads'?'app_downloads':'website_visits';try{await pool.query(`UPDATE site_stats SET ${col}=${col}+1,updated_at=NOW() WHERE id=1`)}catch(e){console.warn('site stat update failed:',e.message)}}
async function getSiteStats(){if(!useDb)return{websiteVisits:0,appDownloads:0};try{const q=await pool.query('SELECT website_visits,app_downloads FROM site_stats WHERE id=1');const r=q.rows[0]||{};return{websiteVisits:Number(r.website_visits||0),appDownloads:Number(r.app_downloads||0)}}catch(e){return{websiteVisits:0,appDownloads:0}}}

